function preferenceSnapshot(){return{version:CALENDAR_PREFERENCE_VERSION,view:calendarState.view,density:calendarState.density,showCaption:calendarState.showCaption,showDestination:calendarState.showDestination,showStatus:calendarState.showStatus,showMedia:calendarState.showMedia,listGroup:calendarState.listGroup,firstDay:calendarState.firstDay,backlogExpanded:calendarState.backlogExpanded,defaultPlanningTime:calendarState.defaultPlanningTime};}
function validateCalendarPreferences(value){if(!value||value.version!==CALENDAR_PREFERENCE_VERSION)return null;const clean={version:CALENDAR_PREFERENCE_VERSION};clean.view=["month","week","list"].includes(value.view)?value.view:"month";clean.density=["compact","comfortable"].includes(value.density)?value.density:"compact";for(const k of ["showCaption","showDestination","showStatus","showMedia","backlogExpanded"])clean[k]=typeof value[k]==="boolean"?value[k]:true;clean.listGroup=["date","channel","schedule"].includes(value.listGroup)?value.listGroup:"date";clean.firstDay=value.firstDay===0?0:1;clean.defaultPlanningTime=/^([01]\d|2[0-3]):[0-5]\d$/.test(value.defaultPlanningTime||"")?value.defaultPlanningTime:"09:00";return clean;}
