function postingPlanRecord(node,index,c){if(node?.type!=="Social Media Posting")return null;const asset=projectAsset(node);if(!asset)return null;const optimistic=interactionOverlay.get(text(node.id)),proposal=calendarState.proposal?.session.snapshot().proposals.find(item=>item.id===text(node.id)),schedule=optimistic?.optimisticSchedule??proposal?.schedule??readPlanningSchedule(node),eligibility=schedulingEligibility(node,c),finalized=eligibility.finalized,editable=eligibility.editable,destinationLabel=asset.platform.toLowerCase()==="facebook"?text(facebookAction(asset,c).selectedDestination?.label):"";return{...asset,title:safePostTitle(asset,c.language),index,schedule,planningSchedule:schedule,proposed:!!proposal,manuallyAdjusted:!!proposal?.manuallyAdjusted,pending:!!optimistic,pendingStage:optimistic?.stage||"",finalized,editable,locked:finalized||!editable,reason:eligibility.reason,eligibility,hasLink:/https:\/\/\S+/u.test(asset.content),mediaPreview:calendarVisuals.mediaPreview(node.images,typeof location!=="undefined"?location.origin:""),destinationLabel};}
