function render(host,c){if(calendarRuntime.rendering){calendarRuntime.followUp=true;calendarRuntime.reentryCount+=1;scheduleDiagnostic("render_reentry",{lifecycleGeneration:c?.requestLifecycleGeneration||0,resultCategory:"coalesced"});return;}calendarRuntime.rendering=true;try{return renderCore(host,c);}finally{calendarRuntime.rendering=false;if(calendarRuntime.followUp){calendarRuntime.followUp=false;queueMicrotask(()=>{if(mounted?.host===host&&mounted?.context===c)render(host,c);});}}}

function feedback(host,msg){const x=host.querySelector?.(".cw-feedback");if(x)x.textContent=msg;}
function facebookPreflightFailure(result,t){const code=result?.status||result?.classification||"";if(code==="approval_stale"||code==="approval_version_outdated")return t.approvalServerStale;if(code==="destination_missing"||code==="destination_unavailable"||code==="destination_connection_mismatch")return t.facebookDestinationUnavailable;if(code==="connection_unavailable"||code==="credential_missing"||code==="credential_revoked"||code==="token_expired")return t.facebookConnectionUnavailable;if(code==="already_published")return t.facebookAlreadyPublished;if(code==="authentication_required"||code==="board_edit_access_required"||code==="board_not_found")return t.facebookAuthorizationFailed;return t.facebookPublishVerifyFailed;}
function blockerMessage(code,lang="en"){const de=lang==="de",messages={NODE_MISSING:["This content no longer exists on the current Board.","Dieser Inhalt existiert nicht mehr auf dem aktuellen Board."],BOARD_CHANGED:["The current Board changed. Open the content on this Board and try again.","Das aktuelle Board wurde gewechselt. Öffne den Inhalt auf diesem Board und versuche es erneut."],ACCESS_REVOKED:["You no longer have permission to plan this content.","Du hast keine Berechtigung mehr, diesen Inhalt zu planen."],ROLE_NOT_SCHEDULABLE:["Only Social Media Posting content can be planned here.","Hier können nur Social-Media-Beiträge geplant werden."],PRIMARY_CONTENT_MISSING:["Add the missing post content before planning a date.","Ergänze den fehlenden Post-Inhalt, bevor du ein Datum planst."],PLATFORM_MISSING:["Choose a platform before planning this post.","Wähle eine Plattform aus, bevor du diesen Post planst."],PLATFORM_UNSUPPORTED:["Choose a supported platform before planning this post.","Wähle eine unterstützte Plattform aus, bevor du diesen Post planst."],READINESS_INCOMPLETE:["Complete the missing required fields before planning a date.","Ergänze die fehlenden Pflichtfelder, bevor du ein Datum planst."],SCHEDULE_DATE_INVALID:["Enter a valid planning date.","Gib ein gültiges Planungsdatum ein."],SCHEDULE_TIME_INVALID:["Enter a valid planning time.","Gib eine gültige Planungszeit ein."],TIMEZONE_REQUIRED:["Choose a timezone for this plan.","Wähle eine Zeitzone für diese Planung."],TIMEZONE_INVALID:["Choose a valid timezone for this plan.","Wähle eine gültige Zeitzone für diese Planung."],CONTENT_CHANGED:["This post changed while the scheduling dialog was open. Review the current version.","Dieser Post wurde geändert, während der Planungsdialog geöffnet war. Prüfe die aktuelle Version."],STATUS_CHANGED:["The editorial status changed while the dialog was open. Review the current status.","Der redaktionelle Status wurde während des Dialogs geändert. Prüfe den aktuellen Status."],SCHEDULE_CHANGED:["The schedule changed while the dialog was open. Review the current plan.","Die Planung wurde während des Dialogs geändert. Prüfe den aktuellen Plan."],BOARD_UNSAVED:["Save the Board before changing its schedule.","Speichere das Board, bevor du die Planung änderst."],SCHEDULE_PENDING:["This schedule is already being saved.","Diese Planung wird bereits gespeichert."],SCHEDULE_CONFLICT:["The Board or schedule changed. Reload and try again.","Das Board oder die Planung wurde geändert. Lade neu und versuche es erneut."],PUBLICATION_FINALIZED:["A finalized publication cannot be rescheduled.","Eine abgeschlossene Veröffentlichung kann nicht neu geplant werden."],SCHEDULE_FAILED:["The schedule could not be saved. The previous schedule remains active.","Die Planung konnte nicht gespeichert werden. Die vorherige Planung bleibt aktiv."]};return(messages[code]||["This action is no longer available. Review the current content.","Diese Aktion ist nicht mehr verfügbar. Prüfe den aktuellen Inhalt."])[de?1:0];}
function resolveNode(c,nodeId,expected={}){if(c.resolveCurrentContentNode)return c.resolveCurrentContentNode(nodeId,expected);const node=c.getNode?.(text(nodeId));return{node,exists:!!node,accessValid:c.canEdit===true&&!c.publicViewer,boardValid:!expected.boardId||expected.boardId===c.boardId,lifecycleValid:true,reasonCode:node?"":"NODE_MISSING"};}
